// @effect-diagnostics nodeBuiltinImport:off globalFetch:off globalTimers:off - native requests for the standalone CI probe.
import * as NodeFSP from "node:fs/promises";
import * as NodePath from "node:path";
import * as NodeChildProcess from "node:child_process";
import * as NodeTimersPromises from "node:timers/promises";

export async function startCold(root: string, url: string, output: string, secret: string) {
  // measure.ts calls prepare(), so regenerate only in a disposable CLI copy. Later uploads
  // must still read the frozen generated bytes, even if Node's type stripping changes.
  const cliRoot = `${output}.cli`;
  await NodeFSP.cp(NodePath.join(root, "host"), NodePath.join(cliRoot, "host"), {
    recursive: true,
  });
  await NodeFSP.copyFile(
    NodePath.join(root, "package.json"),
    NodePath.join(cliRoot, "package.json"),
  );
  await NodeFSP.symlink(
    NodePath.join(root, "node_modules"),
    NodePath.join(cliRoot, "node_modules"),
    "dir",
  );
  const child = NodeChildProcess.spawn(
    process.execPath,
    [
      "--experimental-strip-types",
      NodePath.join(cliRoot, "host/measure.ts"),
      "--url",
      url,
      "--fixture",
      NodePath.join(root, "fixture"),
      "--output",
      output,
    ],
    { env: { ...process.env, PROBE_SECRET: secret }, stdio: ["ignore", "pipe", "pipe"] },
  );
  let stdout = "";
  let stderr = "";
  child.stdout.on("data", (chunk: Buffer) => {
    stdout += chunk.toString();
  });
  child.stderr.on("data", (chunk: Buffer) => {
    stderr += chunk.toString();
  });
  const completed = new Promise<{ exit: number; stdout: string; stderr: string }>(
    (resolve, reject) => {
      child.once("error", reject);
      child.once("close", (exit) => resolve({ exit: exit ?? -1, stdout, stderr }));
    },
  );
  // The frozen request times out in 60s; this only contains a stuck CLI process we spawned.
  const timeout = globalThis.setTimeout(() => child.kill("SIGKILL"), 100_000);
  void completed.finally(() => clearTimeout(timeout)).catch(() => {});
  return completed;
}

export async function rootTraffic(
  url: string,
  session: string,
  secret: string,
  active: () => boolean,
) {
  for (let i = 0; i < 20 && active(); i++) {
    await fetch(`${url}/root/status?session=${session}`, {
      headers: { authorization: `Bearer ${secret}` },
      signal: AbortSignal.timeout(2000),
    })
      .then((response) => response.arrayBuffer())
      .catch(() => {});
    await NodeTimersPromises.setTimeout(100);
  }
}
